    SUB = {"TL": ("lira", "kuruş", "Türk Lirası"), "USD": ("dolar", "sent", "Dolar"), "EUR": ("euro", "sent", "Euro"), "GBP": ("sterlin", "peni", "İngiliz Sterlini")}
    def amt(x, cur):
