                vars["cards_balance_result__" + str(k)] = json.dumps(v, ensure_ascii=False) if isinstance(v, (list, dict)) else str(v)
                if isinstance(v, list):
                    vars["cards_balance_result__" + str(k) + "_count"] = str(len(v))
                if isinstance(v, dict):
                    # A nested answer (data and result objects): their fields as variables too.
                    for k2, v2 in v.items():
                        vars["cards_balance_result__" + str(k) + "__" + str(k2)] = json.dumps(v2, ensure_ascii=False) if isinstance(v2, (list, dict)) else str(v2)
                        if isinstance(v2, list):
                            vars["cards_balance_result__" + str(k) + "__" + str(k2) + "_count"] = str(len(v2))
